/**
 * Subcommand: proof — list the replayed delegation cases that back the tier
 * rules, from the summary shipped inside the package.
 *
 *   sprag proof           # counts and one row per case
 *   sprag proof --json    # the summary JSON as is
 *
 * The summary is evals/summary.json, generated by scripts/evals/build.mjs. It is
 * located from this module, not from the working directory or process.argv[1].
 */
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { userLanguage } from '../config.js';

const SUMMARY_PATH = join(dirname(fileURLToPath(import.meta.url)), '..', '..', 'evals', 'summary.json');
const PROOF_URL = 'https://sprag.io/proof/';

const VERDICT = {
  en: { ok: 'relayable', partial: 'partial', fail: 'missed' },
  ko: { ok: '그대로 전달', partial: '부분', fail: '놓침' },
};

function loadSummary(path) {
  try {
    return JSON.parse(readFileSync(path, 'utf8'));
  } catch {
    return null;
  }
}

function pad(text, width) {
  const s = String(text);
  return s + ' '.repeat(Math.max(0, width - displayWidth(s)));
}

// Hangul and other wide characters take two terminal columns.
function displayWidth(s) {
  let w = 0;
  for (const ch of s) w += /[ᄀ-ᅟ⺀-꓏가-힣豈-﫿＀-｠]/.test(ch) ? 2 : 1;
  return w;
}

export function formatProof(summary, lang) {
  const ko = lang === 'ko';
  const lines = [];
  lines.push(
    ko
      ? `재생한 위임 사례 ${summary.cases}건, 실행 ${summary.runs}회, 라운드 ${summary.rounds.length}개 (최근 ${summary.latest})`
      : `${summary.cases} replayed delegations, ${summary.runs} runs, ${summary.rounds.length} rounds (latest ${summary.latest})`,
  );
  lines.push('');
  const head = ko ? ['사례', '추천 설정', '판정', 'Opus 대비'] : ['Case', 'Setup', 'Verdict', 'vs Opus'];
  const rows = summary.items.map((it) => [
    it.title[lang] || it.title.en,
    it.recommendedLabel || it.recommended,
    VERDICT[lang][it.recommendedVerdict] || it.recommendedVerdict,
    it.savingsPct > 0 ? `-${it.savingsPct.toFixed(1)}%` : `+${Math.abs(it.savingsPct).toFixed(1)}%`,
  ]);
  const widths = head.map((h, i) => Math.max(displayWidth(h), ...rows.map((r) => displayWidth(r[i]))));
  const row = (cells) => cells.map((c, i) => pad(c, widths[i])).join('  ').trimEnd();
  lines.push(row(head));
  for (const r of rows) lines.push(row(r));
  lines.push('');
  lines.push(ko ? `모든 실행 기록: ${PROOF_URL}` : `Every run: ${PROOF_URL}`);
  return lines.join('\n');
}

export async function run({ args = [], hasFlag, summaryPath = SUMMARY_PATH } = {}) {
  const summary = loadSummary(summaryPath);
  if (!summary) {
    console.log(`No replayed-delegation summary in this install. See ${PROOF_URL}`);
    return;
  }
  if (hasFlag?.('--json') || args.includes('--json')) {
    console.log(JSON.stringify(summary, null, 2));
    return;
  }
  console.log(formatProof(summary, userLanguage()));
}
